sp_widget.client_script:
/**
 * File Manager Widget — Client Script (AngularJS Controller + Link Function)
 * ServiceNow Service Portal Widget
 */

api.controller = function ($scope, $http, $timeout) {
    var c = this;

    /* ===================================================
       STATE
    =================================================== */
    c.view            = 'home';        // 'home' | 'allfiles' | 'folders' | 'files' | 'shared' | 'recycle' | 'storage'
    c.currentFolder   = '';
    c.currentFolderName = '';
    c.searchText      = '';
    c.loading         = false;

    // Breadcrumb path: array of {id, name}
    c.breadcrumb      = [];

    // Sorting & Filtering
    c.folderSort      = 'folder_name';
    c.fileSort        = 'filename';
    c.fileTypeFilter  = '';

    // Modals
    c.showFolderModal        = false;
    c.showShareModal         = false;
    c.showEditFileModal      = false;
    c.showUploadFolderPicker = false;
    c.previewFile            = null;

    // Upload Destination Picker State
    c.targetUploadFolder     = '';
    c.targetUploadFolderName = '';

    // Folder Create / Rename
    c.newFolderName        = '';
    c.newFolderDescription = '';
    c.editFolderTarget     = null;     // null = create, object = rename

    // Share State
    c.shareRecipientType    = 'user';  // 'user' | 'group'
    c.selectedUser          = '';
    c.selectedGroup         = '';
    c.sharePermission       = 'Viewer';
    c.shareExpirationDate   = '';
    c.shareTarget           = null;
    c.shareType             = 'file';

    c.userSearchText        = '';
    c.userSearchLoading     = false;
    c.userSearchError       = '';
    c.userSearchTimer       = null;

    c.groupSearchText       = '';
    c.groupSearchLoading    = false;
    c.groupSearchError      = '';
    c.groupSearchTimer      = null;

    // Edit File Description State
    c.editFileTarget      = null;
    c.editFileDescription = '';

    // Confirmation Modal
    c.confirmModal = {
        show: false, title: '', message: '',
        confirmLabel: 'Confirm', danger: false,
        icon: 'fa-check', onConfirm: angular.noop
    };

    // Right-Click Context Menu
    c.contextMenu = {
        show: false,
        x: 0,
        y: 0,
        item: null,
        type: ''
    };

    // Upload State
    c.uploading         = false;
    c.uploadProgress    = 0;
    c.uploadIndex       = 0;
    c.uploadTotal       = 0;
    c.uploadCurrentName = '';

    // Selection
    c.allSelected = false;

    // Drag and Drop
    c.dragOver = false;

    // Alert Messages
    c.message = '';
    c.error   = '';

    /* ===================================================
       NAVIGATION
    =================================================== */

    c.goHome = function () {
        c.view              = 'home';
        c.currentFolder     = '';
        c.currentFolderName = '';
        c.searchText        = '';
        c.breadcrumb        = [];
        _clearAlerts();
        _clearSelection();
        c.closeContextMenu();
    };

    c.setView = function (view) {
        c.view              = view;
        c.currentFolder     = '';
        c.currentFolderName = '';
        c.searchText        = '';
        c.breadcrumb        = [];
        _clearAlerts();
        _clearSelection();
        c.closeContextMenu();
    };

    c.openFolder = function (folder) {
        if (!folder) return;

        if (c.view !== 'files') {
            c.breadcrumb = [
                { id: '', name: 'Folders' },
                { id: folder.sys_id, name: folder.folder_name }
            ];
        } else {
            c.breadcrumb.push({ id: folder.sys_id, name: folder.folder_name });
        }

        c.currentFolder     = folder.sys_id;
        c.currentFolderName = folder.folder_name;
        c.view              = 'files';
        c.searchText        = '';
        _clearAlerts();
        _clearSelection();
        c.closeContextMenu();
    };

    c.openFolderById = function (folderId) {
        if (!folderId) return;
        var folder = (c.data.folders || []).concat(c.data.sharedFolders || []).filter(function (f) {
            return f.sys_id === folderId;
        })[0];
        if (folder) c.openFolder(folder);
    };

    c.navigateBreadcrumb = function (index) {
        var crumb = c.breadcrumb[index];
        if (!crumb) return;

        c.breadcrumb = c.breadcrumb.slice(0, index + 1);

        if (!crumb.id) {
            c.view              = 'folders';
            c.currentFolder     = '';
            c.currentFolderName = '';
        } else {
            c.currentFolder     = crumb.id;
            c.currentFolderName = crumb.name;
            c.view              = 'files';
        }

        c.searchText = '';
        _clearSelection();
        c.closeContextMenu();
    };

    c.navigateBack = function () {
        if (c.breadcrumb.length > 2) {
            c.navigateBreadcrumb(c.breadcrumb.length - 2);
        } else {
            c.setView('folders');
        }
    };

    /* ===================================================
       FOLDER & FILE QUERIES
    =================================================== */

    /** All folders where user can add files (owned or editor) */
    c.editableFolders = function () {
        var owned = (c.data.folders || []);
        var sharedEdit = (c.data.sharedFolders || []).filter(function (f) {
            return f.can_edit;
        });
        return owned.concat(sharedEdit);
    };

    c.foldersInCurrentFolder = function () {
        var list = (c.data.folders || []).concat(c.data.sharedFolders || []);
        var seen = {};
        return list.filter(function (f) {
            if (!f || seen[f.sys_id]) return false;
            seen[f.sys_id] = true;
            return (f.parent_folder || '') === (c.currentFolder || '');
        });
    };

    c.filesInCurrentFolder = function () {
        var list = (c.data.files || []).concat(c.data.sharedFiles || []);
        var seen = {};
        return list.filter(function (f) {
            if (!f || seen[f.sys_id]) return false;
            seen[f.sys_id] = true;
            return (f.folder || '') === (c.currentFolder || '');
        });
    };

    c.currentFolderCanEdit = function () {
        if (!c.currentFolder) return false;
        var match = (c.data.folders || []).concat(c.data.sharedFolders || []).filter(function (f) {
            return f.sys_id === c.currentFolder;
        })[0];
        return match && match.can_edit;
    };

    c.getFolderName = function (folderId, file) {
        if (file && file.folder_name) return file.folder_name;
        if (!folderId) return '';
        var f = (c.data.folders || []).concat(c.data.sharedFolders || []).filter(function (item) {
            return item.sys_id === folderId;
        })[0];
        return f ? f.folder_name : '';
    };

    c.allFilesFiltered = function () {
        return (c.data.files || []).filter(function (file) {
            // Search text filter
            if (c.searchText) {
                var hit = (file.filename || '').toLowerCase().indexOf(c.searchText.toLowerCase()) !== -1;
                if (!hit) return false;
            }

            // Type filter
            if (!c.fileTypeFilter) return true;

            var ext = (file.file_extension || '').toLowerCase();
            switch (c.fileTypeFilter) {
                case 'image':
                    return ['png','jpg','jpeg','gif','webp','bmp','svg'].indexOf(ext) !== -1;
                case 'document':
                    return ['doc','docx','odt','rtf','txt','md','xls','xlsx','csv','ppt','pptx'].indexOf(ext) !== -1;
                case 'pdf':
                    return ext === 'pdf';
                case 'archive':
                    return ['zip','rar','7z','tar','gz'].indexOf(ext) !== -1;
                default:
                    return true;
            }
        });
    };

    c.searchFiles = function (file) {
        if (!c.searchText) return true;
        return (file.filename || '').toLowerCase().indexOf(c.searchText.toLowerCase()) !== -1;
    };

    c.searchFolders = function (folder) {
        if (!c.searchText) return true;
        return (folder.folder_name || '').toLowerCase().indexOf(c.searchText.toLowerCase()) !== -1;
    };

    /* ===================================================
       SORTING
    =================================================== */

    c.toggleSort = function (field) {
        if (c.fileSort === field)            c.fileSort = '-' + field;
        else if (c.fileSort === '-' + field) c.fileSort = field;
        else c.fileSort = field;
    };

    c.getSortIcon = function (field) {
        if (c.fileSort === field)       return 'fa-sort-asc';
        if (c.fileSort === '-' + field) return 'fa-sort-desc';
        return 'fa-sort';
    };

    /* ===================================================
       SERVER ACTIONS & REFRESH
    =================================================== */

    c.runAction = function (action, values) {
        values        = values || {};
        values.action = action;
        _clearAlerts();

        return c.server.get(values).then(function (res) {
            var returned = (res && res.data) ? res.data : res;
            if (returned) {
                if (returned.files || returned.folders) {
                    c.data = returned;
                }
                if (returned.error)   c.error   = returned.error;
                if (returned.success) c.message = returned.success;
            }
            return returned || {};
        }, function () {
            c.error = 'Server request failed. Please try again.';
            return { error: c.error };
        });
    };

    c.refresh = function () {
        c.loading = true;
        _clearAlerts();

        return c.server.get({ action: 'refresh' }).then(function (res) {
            c.loading = false;
            var returned = (res && res.data) ? res.data : res;
            if (returned && (returned.files || returned.folders)) {
                c.data = returned;
            }
            return c.data;
        }, function () {
            c.loading = false;
            c.error = 'Unable to refresh. Please try again.';
        });
    };

    /* ===================================================
       UPLOAD FILES WITH FOLDER PICKER MODAL
       (Asks which folder to upload to!)
    =================================================== */

    c.openUploadFolderPicker = function () {
        var available = c.editableFolders();
        if (c.currentFolder && c.currentFolderCanEdit()) {
            c.targetUploadFolder     = c.currentFolder;
            c.targetUploadFolderName = c.currentFolderName;
        } else if (available.length > 0) {
            c.targetUploadFolder     = available[0].sys_id;
            c.targetUploadFolderName = available[0].folder_name;
        } else {
            c.targetUploadFolder     = '';
            c.targetUploadFolderName = '';
        }
        c.showUploadFolderPicker = true;
    };

    c.onPickerFilesSelected = function (inputEl) {
        var files = inputEl ? inputEl.files : null;
        if (!files || !files.length) return;
        var folderId = c.targetUploadFolder;

        var run = function () {
            c.showUploadFolderPicker = false;
            _uploadFilesToFolder(files, folderId);
            if (inputEl && inputEl.value !== undefined) inputEl.value = '';
        };

        if ($scope.$$phase) {
            run();
        } else {
            $scope.$apply(run);
        }
    };

    c.onDirectFilesSelected = function (inputEl) {
        var files = inputEl ? inputEl.files : null;
        if (!files || !files.length) return;
        var folderId = c.currentFolder;

        var run = function () {
            _uploadFilesToFolder(files, folderId);
            if (inputEl && inputEl.value !== undefined) inputEl.value = '';
        };

        if ($scope.$$phase) {
            run();
        } else {
            $scope.$apply(run);
        }
    };

    function _uploadFilesToFolder(fileList, folderId) {
        var selectedFiles = Array.prototype.slice.call(fileList || []);
        if (!selectedFiles.length) return;

        if (!folderId) {
            c.error = 'Please select a destination folder before uploading.';
            return;
        }

        c.uploading         = true;
        c.uploadProgress    = 0;
        c.uploadIndex       = 0;
        c.uploadTotal       = selectedFiles.length;
        c.uploadCurrentName = '';
        c.error             = '';

        var failedFiles = [];

        function uploadNext() {
            if (c.uploadIndex >= selectedFiles.length) {
                c.uploading = false;
                c.refresh().then(function () {
                    if (failedFiles.length) {
                        c.error = 'Failed to upload: ' + failedFiles.join(', ');
                    } else {
                        c.message = selectedFiles.length === 1
                            ? '"' + selectedFiles[0].name + '" uploaded successfully.'
                            : selectedFiles.length + ' files uploaded successfully.';
                    }
                });
                return;
            }

            var file      = selectedFiles[c.uploadIndex];
            var extension = '';
            if (file.name.indexOf('.') !== -1)
                extension = file.name.split('.').pop().toLowerCase();

            c.uploadCurrentName = file.name;
            c.uploadProgress    = Math.round((c.uploadIndex / selectedFiles.length) * 100);
            c.uploadIndex++;

            c.runAction('create_file', {
                filename:     file.name,
                extension:    extension,
                content_type: file.type || 'application/octet-stream',
                file_size:    file.size,
                folder:       folderId
            }).then(function (result) {
                if (result.error || !result.file_sys_id) {
                    failedFiles.push(file.name);
                    uploadNext();
                    return;
                }

                var uploadUrl =
                    '/api/now/attachment/file' +
                    '?table_name=x_1830514_fm_file' +
                    '&table_sys_id=' + encodeURIComponent(result.file_sys_id) +
                    '&file_name='    + encodeURIComponent(file.name);

                var token = window.g_ck || (c.data && c.data.g_ck) || '';
                var headers = {
                    'Content-Type': undefined,
                    'Accept':       'application/json'
                };
                if (token) headers['X-UserToken'] = token;

                $http.post(uploadUrl, file, {
                    transformRequest: angular.identity,
                    headers: headers
                }).then(function () {
                    c.uploadProgress = Math.round((c.uploadIndex / selectedFiles.length) * 100);
                    uploadNext();
                }, function () {
                    failedFiles.push(file.name);
                    uploadNext();
                });
            });
        }

        uploadNext();
    }

    /* ===================================================
       CREATE & RENAME FOLDER
    =================================================== */

    c.openFolderModal = function () {
        c.newFolderName        = '';
        c.newFolderDescription = '';
        c.editFolderTarget     = null;
        c.showFolderModal      = true;
    };

    c.openRenameFolder = function (folder) {
        c.newFolderName        = folder.folder_name;
        c.newFolderDescription = '';
        c.editFolderTarget     = folder;
        c.showFolderModal      = true;
    };

    c.closeFolderModal = function () {
        c.showFolderModal      = false;
        c.editFolderTarget     = null;
        c.newFolderName        = '';
        c.newFolderDescription = '';
    };

    c.onFolderNameKey = function ($event) {
        if ($event.keyCode === 13) {
            if (c.editFolderTarget) c.renameFolder();
            else c.createFolder();
        }
    };

    c.createFolder = function () {
        var name = (c.newFolderName || '').trim();
        if (!name) { c.error = 'Please enter a folder name.'; return; }

        c.runAction('create_folder', {
            folder_name:   name,
            description:   c.newFolderDescription || '',
            parent_folder: c.currentFolder || ''
        }).then(function (result) {
            if (result.error) return;
            c.closeFolderModal();
            c.refresh();
        });
    };

    c.renameFolder = function () {
        var name = (c.newFolderName || '').trim();
        if (!name) { c.error = 'Please enter a folder name.'; return; }

        c.runAction('rename_folder', {
            sys_id:      c.editFolderTarget.sys_id,
            folder_name: name
        }).then(function (result) {
            if (result.error) return;
            if (c.currentFolder === c.editFolderTarget.sys_id) {
                c.currentFolderName = name;
                c.breadcrumb.forEach(function (b) {
                    if (b.id === c.editFolderTarget.sys_id) b.name = name;
                });
            }
            c.closeFolderModal();
            c.refresh();
        });
    };

    /* ===================================================
       SHARE MODAL (Supports Users, Groups & Expiration)
    =================================================== */

    c.openShare = function (item, type) {
        c.shareTarget           = item;
        c.shareType             = type;
        c.shareRecipientType    = 'user';
        c.selectedUser          = '';
        c.selectedGroup         = '';
        c.sharePermission       = 'Viewer';
        c.shareExpirationDate   = '';
        c.userSearchText        = '';
        c.userSearchError       = '';
        c.groupSearchText       = '';
        c.groupSearchError      = '';
        if (c.data) {
            c.data.users  = [];
            c.data.groups = [];
        }
        c.showShareModal = true;
    };

    c.setShareRecipientType = function (type) {
        c.shareRecipientType = type;
        c.selectedUser       = '';
        c.selectedGroup      = '';
        c.userSearchText     = '';
        c.groupSearchText    = '';
        c.userSearchError    = '';
        c.groupSearchError   = '';
        if (c.data) {
            c.data.users  = [];
            c.data.groups = [];
        }
    };

    c.searchUsers = function () {
        if (c.userSearchTimer) $timeout.cancel(c.userSearchTimer);

        var term = (c.userSearchText || '').trim();
        c.selectedUser    = '';
        c.userSearchError = '';
        if (c.data) c.data.users = [];

        if (term.length < 2) {
            c.userSearchLoading = false;
            return;
        }

        c.userSearchTimer = $timeout(function () {
            c.userSearchLoading = true;
            c.server.get({
                action:      'search_users',
                search_term: term
            }).then(function (res) {
                if (term !== (c.userSearchText || '').trim()) return;
                var ret = (res && res.data) ? res.data : res;
                c.data.users        = (ret && ret.users) || [];
                c.userSearchLoading = false;
            }, function () {
                c.userSearchLoading = false;
                c.userSearchError   = 'Unable to search users.';
            });
        }, 300);
    };

    c.searchGroups = function () {
        if (c.groupSearchTimer) $timeout.cancel(c.groupSearchTimer);

        var term = (c.groupSearchText || '').trim();
        c.selectedGroup    = '';
        c.groupSearchError = '';
        if (c.data) c.data.groups = [];

        if (term.length < 2) {
            c.groupSearchLoading = false;
            return;
        }

        c.groupSearchTimer = $timeout(function () {
            c.groupSearchLoading = true;
            c.server.get({
                action:      'search_groups',
                search_term: term
            }).then(function (res) {
                if (term !== (c.groupSearchText || '').trim()) return;
                var ret = (res && res.data) ? res.data : res;
                c.data.groups        = (ret && ret.groups) || [];
                c.groupSearchLoading = false;
            }, function () {
                c.groupSearchLoading = false;
                c.groupSearchError   = 'Unable to search groups.';
            });
        }, 300);
    };

    c.shareItem = function () {
        if (!c.shareTarget) {
            c.error = 'No item selected to share.';
            return;
        }

        if (c.shareRecipientType === 'user' && !c.selectedUser) {
            c.error = 'Please select a user to share with.';
            return;
        }

        if (c.shareRecipientType === 'group' && !c.selectedGroup) {
            c.error = 'Please select a group to share with.';
            return;
        }

        c.runAction('share', {
            sys_id:          c.shareTarget.sys_id,
            type:            c.shareType,
            recipient_type:  c.shareRecipientType,
            user_id:         c.selectedUser,
            group_id:        c.selectedGroup,
            permission:      c.sharePermission,
            expiration_date: c.shareExpirationDate || ''
        }).then(function (result) {
            if (result.error) return;
            c.showShareModal = false;
            c.shareTarget    = null;
            c.refresh();
        });
    };

    /* ===================================================
       EDIT FILE DESCRIPTION
    =================================================== */

    c.openEditFile = function (file) {
        c.editFileTarget      = file;
        c.editFileDescription = file.description || '';
        c.showEditFileModal   = true;
    };

    c.saveEditFile = function () {
        if (!c.editFileTarget) return;
        c.runAction('update_file', {
            sys_id:      c.editFileTarget.sys_id,
            description: c.editFileDescription
        }).then(function (result) {
            if (!result.error) {
                c.showEditFileModal = false;
                c.editFileTarget    = null;
                c.refresh();
            }
        });
    };

    /* ===================================================
       CONFIRMATION & DELETION HELPERS
    =================================================== */

    function _confirm(opts) {
        c.confirmModal = {
            show:         true,
            title:        opts.title        || 'Are you sure?',
            message:      opts.message      || '',
            confirmLabel: opts.confirmLabel || 'Confirm',
            danger:       opts.danger       !== false,
            icon:         opts.icon         || 'fa-check',
            onConfirm:    opts.onConfirm    || angular.noop
        };
    }

    c.confirmDeleteFile = function (file) {
        _confirm({
            title:        'Move to Recycle Bin',
            message:      'Move "' + file.filename + '" to the Recycle Bin?',
            confirmLabel: 'Move to Bin',
            icon:         'fa-trash',
            onConfirm:    function () { c.deleteFile(file); }
        });
    };

    c.confirmDeleteFolder = function (folder) {
        _confirm({
            title:        'Move Folder to Recycle Bin',
            message:      'Move folder "' + folder.folder_name + '" to the Recycle Bin? Note: All subfolders and files inside must be removed or moved first.',
            confirmLabel: 'Move to Bin',
            icon:         'fa-trash',
            onConfirm:    function () { c.deleteFolder(folder); }
        });
    };

    c.confirmPermanentDeleteFile = function (file) {
        _confirm({
            title:        'Delete File Permanently',
            message:      'Permanently delete "' + file.filename + '"? This action CANNOT be undone.',
            confirmLabel: 'Delete Permanently',
            icon:         'fa-times',
            danger:       true,
            onConfirm:    function () { c.deleteFilePermanent(file); }
        });
    };

    c.confirmPermanentDeleteFolder = function (folder) {
        _confirm({
            title:        'Delete Folder Permanently',
            message:      'Permanently delete folder "' + folder.folder_name + '"? This action CANNOT be undone.',
            confirmLabel: 'Delete Permanently',
            icon:         'fa-times',
            danger:       true,
            onConfirm:    function () { c.deleteFolderPermanent(folder); }
        });
    };

    c.confirmDeleteSelected = function () {
        var count = c.selectedCount();
        _confirm({
            title:        'Delete Selected Files',
            message:      'Move ' + count + ' selected file(s) to the Recycle Bin?',
            confirmLabel: 'Move to Bin',
            icon:         'fa-trash',
            onConfirm:    function () {
                var selected = (c.data.files || []).filter(function (f) { return f._selected; });
                _deleteBatch(selected);
            }
        });
    };

    c.confirmEmptyBin = function () {
        _confirm({
            title:        'Empty Recycle Bin',
            message:      'Permanently delete all files and folders in the Recycle Bin? This action CANNOT be undone.',
            confirmLabel: 'Empty Bin',
            icon:         'fa-trash',
            danger:       true,
            onConfirm:    function () { c.emptyBin(); }
        });
    };

    function _deleteBatch(files) {
        if (!files.length) return;
        var idx = 0;
        function next() {
            if (idx >= files.length) { c.refresh(); return; }
            var f = files[idx++];
            c.runAction('delete_file', { sys_id: f.sys_id }).then(next);
        }
        next();
    }

    /* ===================================================
       CRUD ACTIONS
    =================================================== */

    c.deleteFile = function (file) {
        c.runAction('delete_file', { sys_id: file.sys_id })
            .then(function (r) { if (!r.error) c.refresh(); });
    };

    c.deleteFolder = function (folder) {
        c.runAction('delete_folder', { sys_id: folder.sys_id })
            .then(function (r) { if (!r.error) c.refresh(); });
    };

    c.restoreFile = function (file) {
        c.runAction('restore_file', { sys_id: file.sys_id })
            .then(function (r) { if (!r.error) c.refresh(); });
    };

    c.restoreFolder = function (folder) {
        c.runAction('restore_folder', { sys_id: folder.sys_id })
            .then(function (r) { if (!r.error) c.refresh(); });
    };

    c.deleteFilePermanent = function (file) {
        c.runAction('delete_file_permanent', { sys_id: file.sys_id })
            .then(function (r) { if (!r.error) c.refresh(); });
    };

    c.deleteFolderPermanent = function (folder) {
        c.runAction('delete_folder_permanent', { sys_id: folder.sys_id })
            .then(function (r) { if (!r.error) c.refresh(); });
    };

    c.emptyBin = function () {
        c.runAction('empty_bin').then(function (r) {
            if (!r.error) c.refresh();
        });
    };

    /* ===================================================
       DOWNLOAD & PREVIEW
    =================================================== */

    c.downloadFile = function (file) {
        if (!file || !file.attachment_id) {
            c.error = 'Attachment not found.';
            return;
        }
        window.open(
            '/sys_attachment.do?sys_id=' + encodeURIComponent(file.attachment_id),
            '_blank'
        );
    };

    c.downloadSelected = function () {
        var selected = (c.data.files || []).filter(function (f) { return f._selected; });
        selected.forEach(function (f, i) {
            $timeout(function () { c.downloadFile(f); }, i * 350);
        });
    };

    c.isImage = function (file) {
        if (!file) return false;
        var ext  = (file.file_extension || '').toLowerCase();
        var type = (file.content_type   || '').toLowerCase();
        return type.indexOf('image/') === 0 ||
            ['png','jpg','jpeg','gif','webp','bmp','svg'].indexOf(ext) !== -1;
    };

    c.preview = function (file) {
        if (!file || !file.attachment_id) {
            c.error = 'Attachment not found.';
            return;
        }
        c.previewFile = file;
    };

    c.closePreview = function () {
        c.previewFile = null;
    };

    /* ===================================================
       FILE TYPE ICONS
    =================================================== */

    var _iconMap = {
        png: 'fa fa-file-image-o', jpg: 'fa fa-file-image-o',
        jpeg:'fa fa-file-image-o', gif: 'fa fa-file-image-o',
        webp:'fa fa-file-image-o', bmp: 'fa fa-file-image-o',
        svg: 'fa fa-file-image-o',
        pdf: 'fa fa-file-pdf-o',
        doc: 'fa fa-file-word-o', docx:'fa fa-file-word-o', odt:'fa fa-file-word-o',
        xls: 'fa fa-file-excel-o', xlsx:'fa fa-file-excel-o', csv:'fa fa-file-excel-o',
        ppt: 'fa fa-file-powerpoint-o', pptx:'fa fa-file-powerpoint-o',
        zip: 'fa fa-file-zip-o', rar: 'fa fa-file-zip-o', '7z':'fa fa-file-zip-o',
        tar: 'fa fa-file-zip-o', gz:  'fa fa-file-zip-o',
        mp3: 'fa fa-file-audio-o', wav: 'fa fa-file-audio-o',
        mp4: 'fa fa-file-video-o', avi: 'fa fa-file-video-o', mov:'fa fa-file-video-o',
        js:  'fa fa-file-code-o', html:'fa fa-file-code-o', css:'fa fa-file-code-o',
        json:'fa fa-file-code-o', py:  'fa fa-file-code-o',
        txt: 'fa fa-file-text-o', md:  'fa fa-file-text-o'
    };

    var _colorMap = {
        'fa fa-file-image-o':      'fm-icon-image',
        'fa fa-file-pdf-o':        'fm-icon-pdf',
        'fa fa-file-word-o':       'fm-icon-word',
        'fa fa-file-excel-o':      'fm-icon-excel',
        'fa fa-file-powerpoint-o': 'fm-icon-ppt',
        'fa fa-file-zip-o':        'fm-icon-zip',
        'fa fa-file-audio-o':      'fm-icon-audio',
        'fa fa-file-video-o':      'fm-icon-video',
        'fa fa-file-code-o':       'fm-icon-code',
        'fa fa-file-text-o':       'fm-icon-text'
    };

    c.getFileIcon = function (file) {
        if (!file) return 'fa fa-file-o';
        var ext = (file.file_extension || '').toLowerCase();
        return _iconMap[ext] || 'fa fa-file-o';
    };

    c.getFileIconColor = function (file) {
        var icon = c.getFileIcon(file);
        return _colorMap[icon] || 'fm-icon-default';
    };

    /* ===================================================
       SELECTION HELPERS
    =================================================== */

    c.selectedCount = function () {
        var list = c.view === 'allfiles' ? (c.data.files || []) : c.filesInCurrentFolder();
        return list.filter(function (f) { return f._selected; }).length;
    };

    c.toggleSelectAll = function () {
        c.filesInCurrentFolder().forEach(function (f) {
            f._selected = c.allSelected;
        });
    };

    c.toggleSelectAllGlobal = function () {
        c.allFilesFiltered().forEach(function (f) {
            f._selected = c.allSelected;
        });
    };

    c.onFileSelect = function () {
        var list = c.view === 'allfiles' ? c.allFilesFiltered() : c.filesInCurrentFolder();
        c.allSelected = list.length > 0 && list.every(function (f) {
            return f._selected;
        });
    };

    c.clearSelection = function () {
        (c.data.files || []).forEach(function (f) { f._selected = false; });
        c.allSelected = false;
    };

    /* ===================================================
       RIGHT-CLICK CONTEXT MENU
    =================================================== */

    c.openContextMenu = function (e, item, type) {
        e.preventDefault();
        e.stopPropagation();

        var x = e.clientX || 0;
        var y = e.clientY || 0;

        // Prevent overflow at window boundaries
        var menuWidth  = 180;
        var menuHeight = 220;
        if (x + menuWidth > window.innerWidth)   x = window.innerWidth - menuWidth - 10;
        if (y + menuHeight > window.innerHeight) y = window.innerHeight - menuHeight - 10;

        c.contextMenu = {
            show: true,
            x: x,
            y: y,
            item: item,
            type: type
        };
    };

    c.closeContextMenu = function () {
        if (c.contextMenu.show) {
            c.contextMenu.show = false;
            c.contextMenu.item = null;
        }
    };

    /* ===================================================
       FORMAT BYTES
    =================================================== */

    c.formatBytes = function (bytes) {
        bytes = parseInt(bytes, 10) || 0;
        if (bytes === 0)         return '0 B';
        if (bytes < 1024)        return bytes + ' B';
        if (bytes < 1048576)     return (bytes / 1024).toFixed(1) + ' KB';
        if (bytes < 1073741824)  return (bytes / 1048576).toFixed(1) + ' MB';
        return (bytes / 1073741824).toFixed(2) + ' GB';
    };

    /* ===================================================
       KEYBOARD SHORTCUTS
    =================================================== */

    c.onKeyDown = function ($event) {
        if ($event.keyCode === 27) { // ESC
            c.closeContextMenu();
            if (c.previewFile)            { c.closePreview();                 return; }
            if (c.confirmModal.show)      { c.confirmModal.show = false;      return; }
            if (c.showEditFileModal)      { c.showEditFileModal = false;      return; }
            if (c.showShareModal)         { c.showShareModal = false;         return; }
            if (c.showFolderModal)        { c.closeFolderModal();             return; }
            if (c.showUploadFolderPicker) { c.showUploadFolderPicker = false; return; }
        }
    };

    /* ===================================================
       PRIVATE HELPERS
    =================================================== */

    function _clearAlerts() {
        c.message = '';
        c.error   = '';
    }

    function _clearSelection() {
        c.allSelected = false;
        (c.data && c.data.files || []).forEach(function (f) {
            f._selected = false;
        });
    }
};

/* =====================================================
   LINK FUNCTION
   1. Drag & drop file uploads on [fm-drop-zone]
   2. Right-click contextmenu delegation on [fm-context-item]
===================================================== */
api.link = function ($scope, element) {
    var rootEl = element[0];

    // Right-click delegation
    rootEl.addEventListener('contextmenu', function (e) {
        var target = e.target.closest('[fm-context-item]');
        if (target) {
            e.preventDefault();
            var scope = angular.element(target).scope();
            if (scope && scope.c) {
                var item = scope.file || scope.folder;
                var type = target.getAttribute('fm-context-type');
                if (item && type) {
                    $scope.$apply(function () {
                        scope.c.openContextMenu(e, item, type);
                    });
                }
            }
        }
    });

    // Drag-and-drop support
    function prevent(e) {
        e.preventDefault();
        e.stopPropagation();
    }

    function safeApply(fn) {
        if ($scope.$$phase || ($scope.$root && $scope.$root.$$phase)) {
            if (fn) fn();
        } else {
            $scope.$apply(fn);
        }
    }

    rootEl.addEventListener('dragenter', function (e) {
        if (e.target.closest('[fm-drop-zone]')) {
            prevent(e);
            safeApply(function () { $scope.c.dragOver = true; });
        }
    });

    rootEl.addEventListener('dragover', function (e) {
        if (e.target.closest('[fm-drop-zone]')) {
            prevent(e);
            e.dataTransfer.dropEffect = 'copy';
            safeApply(function () { $scope.c.dragOver = true; });
        }
    });

    rootEl.addEventListener('dragleave', function (e) {
        var dropZone = e.target.closest('[fm-drop-zone]');
        if (dropZone && !dropZone.contains(e.relatedTarget)) {
            prevent(e);
            safeApply(function () { $scope.c.dragOver = false; });
        }
    });

    rootEl.addEventListener('drop', function (e) {
        var dropZone = e.target.closest('[fm-drop-zone]');
        if (dropZone) {
            prevent(e);
            safeApply(function () { $scope.c.dragOver = false; });

            var files = e.dataTransfer && e.dataTransfer.files;
            if (files && files.length && $scope.c && $scope.c.currentFolder) {
                // Upload dropped files into current active folder
                $scope.c.onDirectFilesSelected({ files: files });
            }
        }
    });
};

sp_widget.css:
/* =========================================
   FILE MANAGER — CLEAN MODERN SAAS INTERFACE
   ServiceNow Portal Widget
========================================= */

/* --- RESET & MAIN CONTAINER --- */
.fm-app {
    display: flex;
    width: 100%;
    min-height: 750px;
    background: #f5f7fb;
    color: #263445;
    font-family: Arial, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    position: relative;
    box-sizing: border-box;
}

.fm-app * {
    box-sizing: border-box;
}

/* =========================================
   SIDEBAR
========================================= */

.fm-sidebar {
    width: 235px;
    min-width: 235px;
    background: #ffffff;
    border-right: 1px solid #e7ebf0;
    display: flex;
    flex-direction: column;
    min-height: 750px;
    flex-shrink: 0;
}

.fm-logo {
    height: 72px;
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 0 22px;
    border-bottom: 1px solid #edf0f4;
    font-size: 18px;
    font-weight: 700;
    color: #263445;
    cursor: pointer;
    user-select: none;
}

.fm-logo-icon {
    width: 38px;
    height: 38px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #e9f1ff;
    color: #3478df;
    font-size: 19px;
    flex-shrink: 0;
}

.fm-menu {
    padding: 20px 12px;
    flex: 1;
}

.fm-menu-label {
    color: #9aa5b3;
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 1px;
    padding: 0 12px;
    margin-bottom: 10px;
    text-transform: uppercase;
}

.fm-menu-spaced {
    margin-top: 24px;
}

.fm-menu a {
    display: flex;
    align-items: center;
    gap: 12px;
    height: 42px;
    padding: 0 12px;
    margin-bottom: 4px;
    border-radius: 7px;
    color: #657386;
    font-size: 13px;
    text-decoration: none;
    cursor: pointer;
    transition: all 0.18s ease;
    user-select: none;
}

.fm-menu a i {
    width: 18px;
    font-size: 14px;
    text-align: center;
    flex-shrink: 0;
}

.fm-menu a:hover {
    background: #f0f5ff;
    color: #3478df;
}

.fm-menu a.active {
    background: #eaf1ff;
    color: #3478df;
    font-weight: 600;
}

.fm-badge {
    margin-left: auto;
    min-width: 20px;
    height: 20px;
    padding: 0 6px;
    border-radius: 10px;
    background: #e84444;
    color: #ffffff;
    font-size: 10px;
    font-weight: 700;
    display: flex;
    align-items: center;
    justify-content: center;
}

.fm-count-pill {
    margin-left: auto;
    padding: 2px 7px;
    border-radius: 10px;
    background: #edf1f6;
    color: #68778a;
    font-size: 10px;
    font-weight: 600;
}

.fm-sidebar-footer {
    padding: 16px 20px;
    border-top: 1px solid #edf0f4;
    color: #8491a2;
    font-size: 12px;
    display: flex;
    align-items: center;
    gap: 8px;
}

.fm-sidebar-footer i {
    color: #3478df;
}

/* =========================================
   MAIN CONTENT AREA
========================================= */

.fm-main {
    flex: 1;
    min-width: 0;
    padding: 24px 30px;
    background: #f5f7fb;
    display: flex;
    flex-direction: column;
}

/* =========================================
   TOP HEADER
========================================= */

.fm-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    min-height: 60px;
    margin-bottom: 20px;
    flex-wrap: wrap;
}

.fm-header-title h2 {
    margin: 0 0 4px;
    font-size: 22px;
    font-weight: 700;
    color: #263445;
}

.fm-header-title p {
    margin: 0;
    color: #8a96a5;
    font-size: 12px;
}

.fm-header-actions {
    display: flex;
    align-items: center;
    gap: 10px;
    flex-shrink: 0;
}

.fm-header-search {
    display: flex;
    align-items: center;
    gap: 10px;
    width: 290px;
    height: 40px;
    padding: 0 12px;
    border: 1px solid #e0e6ed;
    border-radius: 7px;
    background: #ffffff;
    transition: border-color 0.15s;
}

.fm-header-search:focus-within {
    border-color: #78a5e8;
    box-shadow: 0 0 0 2px rgba(52, 120, 223, 0.08);
}

.fm-header-search i {
    color: #98a4b2;
    flex-shrink: 0;
}

.fm-header-search input {
    width: 100%;
    min-width: 0;
    border: none !important;
    outline: none !important;
    box-shadow: none !important;
    background: transparent;
    font-size: 12px;
}

.fm-search-clear {
    border: none;
    background: transparent;
    color: #a0aec0;
    cursor: pointer;
    padding: 0;
    display: flex;
    align-items: center;
}

.fm-search-clear:hover {
    color: #4a5568;
}

.fm-refresh-btn {
    width: 40px;
    height: 40px;
    border: 1px solid #e0e6ed;
    border-radius: 7px;
    background: #ffffff;
    color: #657386;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.15s;
}

.fm-refresh-btn:hover {
    color: #3478df;
    background: #f0f5ff;
    border-color: #b8cff4;
}

.fm-refresh-btn.fm-spinning i {
    animation: fm-spin 0.8s linear infinite;
}

@keyframes fm-spin {
    to { transform: rotate(360deg); }
}

/* =========================================
   BREADCRUMB
========================================= */

.fm-breadcrumb {
    display: flex;
    align-items: center;
    gap: 6px;
    margin-bottom: 16px;
    font-size: 12px;
    color: #8a96a5;
    flex-wrap: wrap;
}

.fm-breadcrumb a {
    color: #3478df;
    text-decoration: none;
    cursor: pointer;
}

.fm-breadcrumb a:hover {
    text-decoration: underline;
}

.fm-breadcrumb-sep {
    color: #c4cfdb;
    font-size: 10px;
}

.fm-breadcrumb-current {
    color: #263445;
    font-weight: 600;
}

/* =========================================
   BUTTONS
========================================= */

.fm-button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 7px;
    min-height: 36px;
    padding: 7px 14px;
    border: 1px solid #dfe5ed;
    border-radius: 6px;
    background: #ffffff;
    color: #536174;
    font-size: 12px;
    font-weight: 600;
    cursor: pointer;
    text-decoration: none;
    transition: all 0.15s ease;
    white-space: nowrap;
    position: relative;
}

.fm-button:hover {
    background: #f5f8fc;
    color: #3478df;
    border-color: #b8cff4;
}

.fm-button.fm-primary {
    color: #ffffff;
    background: #3478df;
    border-color: #3478df;
}

.fm-button.fm-primary:hover {
    background: #2867c5;
    color: #ffffff;
}

.fm-button.fm-danger {
    color: #c24c4c;
    background: #fff0f0;
    border-color: #f4dada;
}

.fm-button.fm-danger:hover {
    background: #ffe0e0;
    border-color: #e8b8b8;
}

.fm-button:disabled,
.fm-button[disabled],
.fm-disabled {
    opacity: 0.55;
    cursor: not-allowed;
    pointer-events: none;
}

.fm-back-btn {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 0;
    margin-bottom: 10px;
    border: none;
    background: transparent;
    color: #3478df;
    font-size: 12px;
    font-weight: 600;
    cursor: pointer;
}

.fm-back-btn:hover {
    text-decoration: underline;
}

.fm-restore-btn {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    height: 28px;
    padding: 0 11px;
    border-radius: 5px;
    background: #effaf3;
    color: #268a57;
    border: 1px solid #ccebd8;
    font-size: 11px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.15s;
    white-space: nowrap;
    width: auto !important;
    min-width: auto !important;
}

.fm-restore-btn:hover {
    background: #e2f6e9;
    color: #197344;
    border-color: #a3dcba;
}

.fm-perm-delete-btn {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    height: 28px;
    padding: 0 11px;
    border-radius: 5px;
    background: #fff0f0;
    color: #c24c4c;
    border: 1px solid #f4dada;
    font-size: 11px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.15s;
    white-space: nowrap;
    width: auto !important;
    min-width: auto !important;
}

.fm-perm-delete-btn:hover {
    background: #ffe0e0;
    color: #a72828;
    border-color: #e8b8b8;
}

.fm-recycle-actions {
    display: flex;
    align-items: center;
    gap: 8px;
    justify-content: flex-end;
    white-space: nowrap;
}

/* =========================================
   SECTIONS AND TOOLBARS
========================================= */

.fm-content {
    width: 100%;
}

.fm-section {
    margin-top: 26px;
}

.fm-section-header,
.fm-toolbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 15px;
    margin-bottom: 16px;
    flex-wrap: wrap;
}

.fm-section-header h3,
.fm-toolbar h3 {
    margin: 0 0 4px;
    font-size: 17px;
    font-weight: 700;
    color: #263445;
}

.fm-section-header p,
.fm-toolbar p {
    margin: 0;
    font-size: 12px;
    color: #8a96a5;
}

.fm-toolbar-actions {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
}

.fm-subsection {
    margin-top: 24px;
}

.fm-subsection-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 14px;
}

.fm-subsection h4 {
    font-size: 14px;
    font-weight: 700;
    margin: 0 0 14px;
    color: #344256;
}

/* =========================================
   WELCOME SECTION
========================================= */

.fm-welcome {
    display: flex;
    align-items: center;
    justify-content: space-between;
    min-height: 135px;
    padding: 24px 28px;
    border-radius: 11px;
    background: linear-gradient(110deg, #eaf2ff, #f4f7ff);
    border: 1px solid #e2ebfc;
}

.fm-welcome h3 {
    margin: 0 0 8px;
    color: #263e64;
    font-size: 21px;
    font-weight: 700;
}

.fm-welcome p {
    margin: 0;
    color: #7588a4;
    font-size: 13px;
}

.fm-welcome-icon {
    width: 70px;
    height: 70px;
    border-radius: 50%;
    background: #ffffff;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #3478df;
    font-size: 30px;
    flex-shrink: 0;
    box-shadow: 0 4px 12px rgba(52, 120, 223, 0.12);
}

/* =========================================
   STATISTICS CARDS
========================================= */

.fm-stats {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 14px;
    margin-top: 20px;
}

.fm-stat-card {
    display: flex;
    align-items: center;
    gap: 14px;
    min-height: 90px;
    padding: 16px;
    border: 1px solid #e9edf2;
    border-radius: 9px;
    background: #ffffff;
    transition: all 0.18s ease;
    cursor: default;
}

.fm-stat-card.fm-clickable {
    cursor: pointer;
}

.fm-stat-card.fm-clickable:hover {
    border-color: #b8cff4;
    box-shadow: 0 4px 14px rgba(37, 75, 125, 0.08);
}

.fm-stat-card span {
    display: block;
    color: #8793a3;
    font-size: 11px;
    margin-bottom: 6px;
}

.fm-stat-card strong {
    display: block;
    color: #263445;
    font-size: 22px;
}

.fm-stat-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 42px;
    height: 42px;
    min-width: 42px;
    border-radius: 9px;
    font-size: 17px;
}

.fm-stat-icon.blue   { background: #eaf1ff; color: #3478df; }
.fm-stat-icon.purple { background: #f1eaff; color: #8856cf; }
.fm-stat-icon.green  { background: #e8f8ef; color: #28a365; }
.fm-stat-icon.orange { background: #fff3e0; color: #e07c00; }

/* =========================================
   FOLDER CARDS & GRID
========================================= */

.fm-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 13px;
}

.fm-folder-card {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    min-height: 80px;
    padding: 12px 14px;
    border: 1px solid #e7ebf1;
    border-radius: 9px;
    background: #ffffff;
    transition: all 0.18s ease;
}

.fm-folder-card:hover {
    border-color: #b8cff4;
    box-shadow: 0 4px 14px rgba(37, 75, 125, 0.08);
}

.fm-folder-main {
    display: flex;
    align-items: center;
    gap: 12px;
    flex: 1;
    min-width: 0;
    cursor: pointer;
}

.fm-folder-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 42px;
    height: 42px;
    min-width: 42px;
    border-radius: 9px;
    background: #fff4dc;
    color: #e6a52c;
    font-size: 20px;
}

.fm-card-info {
    display: flex;
    flex-direction: column;
    min-width: 0;
    gap: 4px;
}

.fm-card-info strong {
    color: #344256;
    font-size: 13px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.fm-card-info span {
    color: #95a0ad;
    font-size: 11px;
}

.fm-card-arrow {
    color: #aab4c0;
    font-size: 17px;
    flex-shrink: 0;
}

.fm-card-menu {
    display: flex;
    gap: 4px;
    flex-shrink: 0;
}

.fm-card-menu button {
    width: 28px;
    height: 28px;
    border: none;
    border-radius: 5px;
    background: transparent;
    color: #7e8a99;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.15s;
}

.fm-card-menu button:hover {
    background: #f0f5ff;
    color: #3478df;
}

/* =========================================
   FILE TABLE
========================================= */

.fm-table-wrap {
    width: 100%;
    overflow-x: auto;
    border: 1px solid #e8edf2;
    border-radius: 8px;
    background: #ffffff;
}

.fm-table {
    width: 100%;
    border-collapse: collapse;
    min-width: 580px;
}

.fm-table th {
    padding: 12px 16px;
    text-align: left;
    background: #f8fafd;
    border-bottom: 1px solid #e9edf2;
    color: #8793a3;
    font-size: 10px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.4px;
    white-space: nowrap;
    vertical-align: middle;
}

.fm-table th.fm-sortable {
    cursor: pointer;
    user-select: none;
}

.fm-table th.fm-sortable:hover {
    color: #3478df;
}

.fm-table td {
    padding: 12px 16px;
    border-bottom: 1px solid #eef1f5;
    color: #667386;
    font-size: 12px;
    vertical-align: middle;
}

.fm-table tbody tr:last-child td {
    border-bottom: none;
}

.fm-table tbody tr:hover {
    background: #fafcff;
}

.fm-file-name {
    display: flex;
    align-items: center;
    gap: 10px;
    color: #344256;
    font-weight: 600;
    min-width: 0;
}

.fm-file-name span {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    max-width: 240px;
}

/* File type icon colors */
.fm-file-icon { font-size: 16px; flex-shrink: 0; }
.fm-icon-image  { color: #34a853; }
.fm-icon-pdf    { color: #e84444; }
.fm-icon-word   { color: #2b7cd3; }
.fm-icon-excel  { color: #1e7145; }
.fm-icon-ppt    { color: #d04425; }
.fm-icon-zip    { color: #a1701a; }
.fm-icon-audio  { color: #0d6efd; }
.fm-icon-video  { color: #dc3545; }
.fm-icon-code   { color: #6f42c1; }
.fm-icon-text   { color: #6c757d; }
.fm-icon-default{ color: #6889bd; }

/* Permission badges */
.fm-permission {
    display: inline-block;
    padding: 3px 8px;
    border-radius: 4px;
    font-size: 10px;
    font-weight: 600;
}

.fm-perm-owner  { background: #fff3e0; color: #e07c00; }
.fm-perm-editor { background: #e8f8ef; color: #28a365; }
.fm-perm-viewer { background: #eef4ff; color: #3478df; }

/* Folder link chip in All Files view */
.fm-folder-chip {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    padding: 3px 8px;
    background: #fff8e6;
    color: #c78612;
    border-radius: 4px;
    font-size: 11px;
    font-weight: 600;
    cursor: pointer;
    text-decoration: none;
    max-width: 170px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    transition: background 0.15s;
}

.fm-folder-chip:hover {
    background: #ffeed0;
    text-decoration: underline;
}

.fm-actions {
    display: flex;
    align-items: center;
    gap: 4px;
}

.fm-actions button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 29px;
    height: 29px;
    border: none;
    border-radius: 5px;
    background: transparent;
    color: #718096;
    cursor: pointer;
    transition: all 0.15s;
    flex-shrink: 0;
}

.fm-actions button.fm-restore-btn,
.fm-actions button.fm-perm-delete-btn {
    width: auto !important;
    height: 28px !important;
}

.fm-actions button:hover {
    background: #edf3ff;
    color: #3478df;
}

.fm-actions button.fm-del-btn:hover {
    background: #fff0f0;
    color: #c24c4c;
}

/* =========================================
   DRAG AND DROP ZONE
========================================= */

.fm-drop-zone {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    height: 60px;
    margin-bottom: 16px;
    border: 2px dashed #cdd6e2;
    border-radius: 8px;
    color: #8b99a9;
    font-size: 12px;
    transition: all 0.2s ease;
}

.fm-drop-zone i {
    font-size: 22px;
    color: #8ba0bd;
}

.fm-drop-zone.fm-drag-over {
    border-color: #3478df;
    background: #f0f5ff;
    color: #3478df;
}

.fm-drop-zone.fm-drag-over i {
    color: #3478df;
}

/* =========================================
   UPLOAD PROGRESS
========================================= */

.fm-upload-progress {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 16px;
    padding: 10px 14px;
    background: #ffffff;
    border: 1px solid #e0e6ed;
    border-radius: 7px;
    font-size: 12px;
    color: #536174;
}

.fm-upload-bar {
    flex: 1;
    height: 6px;
    background: #eef2f7;
    border-radius: 3px;
    overflow: hidden;
}

.fm-upload-fill {
    height: 100%;
    background: #3478df;
    border-radius: 3px;
    transition: width 0.3s ease;
}

/* =========================================
   EMPTY STATES
========================================= */

.fm-empty {
    padding: 38px 16px;
    text-align: center;
    color: #98a4b2;
}

.fm-empty > i {
    display: block;
    margin-bottom: 12px;
    font-size: 34px;
    color: #c4cfdb;
}

.fm-empty p {
    margin: 0 0 12px;
    font-size: 12px;
}

/* =========================================
   ALERT MESSAGES
========================================= */

.fm-alert {
    display: flex;
    align-items: center;
    gap: 9px;
    padding: 11px 14px;
    margin-bottom: 16px;
    border-radius: 6px;
    font-size: 12px;
    animation: fm-fadein 0.2s ease;
}

.fm-alert span {
    flex: 1;
}

.fm-alert button {
    margin-left: auto;
    border: none;
    background: transparent;
    font-size: 19px;
    line-height: 1;
    cursor: pointer;
    color: inherit;
    opacity: 0.6;
}

.fm-alert button:hover {
    opacity: 1;
}

.fm-alert-success {
    background: #eaf8ef;
    color: #25844d;
    border: 1px solid #d5efdf;
}

.fm-alert-error {
    background: #fff0f0;
    color: #c24c4c;
    border: 1px solid #f4dada;
}

@keyframes fm-fadein {
    from { opacity: 0; transform: translateY(-4px); }
    to   { opacity: 1; transform: translateY(0); }
}

/* =========================================
   STORAGE
========================================= */

.fm-storage-card {
    display: flex;
    align-items: center;
    gap: 18px;
    padding: 22px 26px;
    border: 1px solid #e6ecf3;
    border-radius: 9px;
    background: #ffffff;
}

.fm-storage-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 52px;
    height: 52px;
    border-radius: 10px;
    background: #eaf1ff;
    color: #3478df;
    font-size: 22px;
    flex-shrink: 0;
}

.fm-storage-card h3 {
    margin: 0 0 5px;
    font-size: 16px;
    color: #344256;
}

.fm-storage-card p {
    margin: 0;
    color: #8a96a5;
    font-size: 12px;
}

.fm-storage-note {
    margin-top: 18px;
    color: #8a96a5;
    font-size: 11px;
    line-height: 1.6;
}

.fm-ext-badge {
    display: inline-block;
    padding: 3px 8px;
    border-radius: 4px;
    background: #f0f4f8;
    color: #536174;
    font-size: 11px;
    font-weight: 600;
    text-transform: uppercase;
}

/* =========================================
   MODALS
========================================= */

.fm-modal-backdrop {
    position: fixed;
    inset: 0;
    z-index: 9999;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 16px;
    background: rgba(25, 38, 55, 0.48);
    animation: fm-fadein 0.2s ease;
}

.fm-modal {
    width: 100%;
    max-width: 440px;
    max-height: 90vh;
    overflow-y: auto;
    padding: 24px;
    border-radius: 11px;
    background: #ffffff;
    box-shadow: 0 15px 50px rgba(0, 0, 0, 0.16);
    animation: fm-modal-in 0.22s ease;
}

@keyframes fm-modal-in {
    from { opacity: 0; transform: scale(0.96) translateY(6px); }
    to   { opacity: 1; transform: scale(1) translateY(0); }
}

.fm-modal-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 20px;
}

.fm-modal-header h3 {
    margin: 0;
    color: #263445;
    font-size: 18px;
    font-weight: 700;
}

.fm-modal-header button {
    width: 30px;
    height: 30px;
    border: none;
    border-radius: 5px;
    background: #f1f4f8;
    color: #68778a;
    font-size: 21px;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    line-height: 1;
}

.fm-modal-header button:hover {
    background: #e5ebf2;
    color: #263445;
}

.fm-modal label {
    display: block;
    margin: 14px 0 6px;
    color: #526174;
    font-size: 12px;
    font-weight: 600;
}

.fm-modal input[type="text"],
.fm-modal select,
.fm-modal textarea {
    width: 100%;
    min-height: 38px;
    padding: 8px 11px;
    border: 1px solid #dce3eb;
    border-radius: 6px;
    outline: none;
    background: #ffffff;
    color: #344256;
    font-size: 12px;
    box-shadow: none;
    transition: border-color 0.15s;
}

.fm-modal input:focus,
.fm-modal select:focus,
.fm-modal textarea:focus {
    border-color: #78a5e8;
    box-shadow: 0 0 0 2px rgba(52, 120, 223, 0.08);
}

.fm-modal textarea {
    resize: vertical;
}

.fm-char-count {
    text-align: right;
    font-size: 10px;
    color: #9aa5b3;
    margin-top: 3px;
}

.fm-modal-actions {
    display: flex;
    justify-content: flex-end;
    gap: 9px;
    margin-top: 22px;
}

/* Folder Picker inside Upload Modal */
.fm-folder-picker-list {
    max-height: 220px;
    overflow-y: auto;
    border: 1px solid #dce3eb;
    border-radius: 6px;
    margin-top: 6px;
    background: #ffffff;
}

.fm-folder-picker-item {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px 12px;
    cursor: pointer;
    border-bottom: 1px solid #f0f4f8;
    transition: background 0.12s;
}

.fm-folder-picker-item:last-child {
    border-bottom: none;
}

.fm-folder-picker-item:hover {
    background: #f5f8fc;
}

.fm-folder-picker-item.selected {
    background: #eef4ff;
    color: #3478df;
}

.fm-folder-picker-item i.fa-folder {
    color: #e6a52c;
    font-size: 16px;
    flex-shrink: 0;
}

.fm-folder-picker-name {
    flex: 1;
    font-size: 12px;
    font-weight: 600;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.fm-folder-picker-perm {
    font-size: 10px;
    color: #8b99a9;
    flex-shrink: 0;
}

.fm-folder-picker-check {
    color: #3478df;
    font-size: 13px;
    flex-shrink: 0;
}

.fm-picker-new-link {
    margin-top: 8px;
    font-size: 11px;
    color: #3478df;
    cursor: pointer;
    display: inline-block;
}

.fm-picker-new-link:hover {
    text-decoration: underline;
}

/* =========================================
   SHARE MODAL
========================================= */

.fm-share-modal {
    max-width: 480px;
}

.fm-user-search {
    display: flex;
    align-items: center;
    gap: 10px;
    width: 100%;
    min-height: 40px;
    padding: 0 12px;
    margin-top: 6px;
    border: 1px solid #d7dfe8;
    border-radius: 6px;
    background: #ffffff;
}

.fm-user-search i {
    color: #8291a2;
    font-size: 13px;
}

.fm-user-search input {
    flex: 1;
    width: 100%;
    min-width: 0;
    height: 36px;
    border: none !important;
    outline: none !important;
    box-shadow: none !important;
    background: transparent;
    font-size: 12px;
}

.fm-search-help {
    margin: 5px 0 12px;
    color: #8995a2;
    font-size: 11px;
}

.fm-user-status {
    padding: 8px 0;
    color: #718096;
    font-size: 12px;
}

.fm-user-status i {
    margin-right: 6px;
}

.fm-user-error {
    color: #c24c4c;
}

.fm-user-results {
    max-height: 180px;
    overflow-y: auto;
    border: 1px solid #e0e6ed;
    border-radius: 6px;
    margin-bottom: 8px;
}

.fm-user-option {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 8px 12px;
    cursor: pointer;
    border-bottom: 1px solid #f0f4f8;
    transition: background 0.12s;
}

.fm-user-option:last-child {
    border-bottom: none;
}

.fm-user-option:hover {
    background: #f5f8fc;
}

.fm-user-selected {
    background: #eef4ff !important;
}

.fm-user-avatar {
    width: 30px;
    height: 30px;
    border-radius: 50%;
    background: #3478df;
    color: #ffffff;
    font-size: 12px;
    font-weight: 700;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
}

.fm-user-info {
    flex: 1;
    min-width: 0;
}

.fm-user-info strong {
    display: block;
    font-size: 12px;
    color: #344256;
}

.fm-user-info span {
    display: block;
    font-size: 10px;
    color: #8a96a5;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

/* =========================================
   CONFIRMATION MODAL
========================================= */

.fm-confirm-modal {
    max-width: 400px;
}

.fm-confirm-text {
    color: #536174;
    font-size: 13px;
    line-height: 1.6;
    margin: 4px 0 16px;
}

/* =========================================
   IMAGE PREVIEW MODAL
========================================= */

.fm-preview-backdrop {
    z-index: 10000;
}

.fm-preview-modal {
    display: flex;
    flex-direction: column;
    width: 100%;
    max-width: 850px;
    max-height: 90vh;
    overflow: hidden;
    border-radius: 10px;
    background: #ffffff;
}

.fm-preview-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 15px;
    padding: 14px 20px;
    border-bottom: 1px solid #e9edf2;
    color: #344256;
    font-size: 13px;
}

.fm-preview-header button {
    width: 30px;
    height: 30px;
    border: none;
    border-radius: 5px;
    background: #f1f4f8;
    color: #68778a;
    font-size: 20px;
    cursor: pointer;
}

.fm-preview-content {
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 250px;
    max-height: 65vh;
    padding: 20px;
    overflow: auto;
    background: #f7f9fc;
}

.fm-preview-content img {
    display: block;
    max-width: 100%;
    max-height: 60vh;
    object-fit: contain;
}

.fm-preview-footer {
    display: flex;
    justify-content: flex-end;
    gap: 10px;
    padding: 12px 20px;
    border-top: 1px solid #e9edf2;
}

/* =========================================
   RIGHT-CLICK CONTEXT MENU
========================================= */

.fm-context-menu {
    position: fixed;
    z-index: 99999;
    min-width: 170px;
    background: #ffffff;
    border: 1px solid #dce3eb;
    border-radius: 8px;
    box-shadow: 0 8px 26px rgba(25, 38, 55, 0.16);
    padding: 6px 0;
    animation: fm-fadein 0.12s ease;
}

.fm-context-item {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 8px 14px;
    font-size: 12px;
    color: #344256;
    cursor: pointer;
    transition: background 0.1s;
}

.fm-context-item:hover {
    background: #f0f5ff;
    color: #3478df;
}

.fm-context-item i {
    width: 16px;
    font-size: 13px;
    text-align: center;
    color: #718096;
}

.fm-context-item:hover i {
    color: #3478df;
}

.fm-context-item.danger {
    color: #c24c4c;
}

.fm-context-item.danger:hover {
    background: #fff0f0;
    color: #c24c4c;
}

.fm-context-item.danger i {
    color: #c24c4c;
}

.fm-context-divider {
    height: 1px;
    background: #eef1f5;
    margin: 4px 0;
}

/* =========================================
   RESPONSIVE DESIGN
========================================= */

@media (max-width: 900px) {
    .fm-sidebar {
        width: 190px;
        min-width: 190px;
    }

    .fm-main {
        padding: 18px;
    }

    .fm-stats {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

@media (max-width: 650px) {
    .fm-app {
        display: block;
    }

    .fm-sidebar {
        width: 100%;
        min-width: 0;
        min-height: auto;
    }

    .fm-menu {
        display: flex;
        flex-wrap: wrap;
        gap: 5px;
        padding: 10px;
    }

    .fm-menu-label {
        display: none;
    }

    .fm-menu a {
        flex: 1 1 42%;
        margin: 0;
    }

    .fm-sidebar-footer {
        display: none;
    }

    .fm-main {
        padding: 14px;
    }

    .fm-header {
        flex-wrap: wrap;
    }

    .fm-header-search {
        width: 100%;
        max-width: 100%;
    }

    .fm-stats {
        grid-template-columns: 1fr;
    }

    .fm-grid {
        grid-template-columns: 1fr;
    }
}

sp_widget.script:
(function () {
    /*
     * File Manager Widget — Server Script
     * ServiceNow Portal Widget (Perfected)
     *
     * Tables used:
     *   x_1830514_fm_file    — File records
     *   x_1830514_fm_folder  — Folder records
     *   x_1830514_fm_share   — Share records
     *
     * Key improvements over original:
     *  - try/catch wrapper around every action and data-load
     *  - rename_folder action added
     *  - empty_bin action added (permanent delete)
     *  - storage.byType breakdown for new storage view
     *  - recycleFiles/recycleFolders include deleted_date
     *  - Shared items loaded via indexed join to avoid N+1 problem
     *  - Consistent error message style
     *  - Input sanitisation before every write
     */

    var FILE_TABLE = 'x_1830514_fm_file';
    var FOLDER_TABLE = 'x_1830514_fm_folder';
    var SHARE_TABLE = 'x_1830514_fm_share';

    var userId = gs.getUserID();

    /* ---- Initialise response ---- */
    data.files = [];
    data.folders = [];
    data.sharedFiles = [];
    data.sharedFolders = [];
    data.recycleFiles = [];
    data.recycleFolders = [];
    data.users = [];
    data.groups = [];
    data.storage = { fileCount: 0, totalBytes: 0, byType: [] };
    data.g_ck = gs.getSession().getSessionToken();
    data.error = '';
    data.success = '';

    try {
        /* ---- Search users (early return) ---- */
        if (input && input.action === 'search_users') {
            searchUsers();
            return;
        }

        /* ---- Search groups (early return) ---- */
        if (input && input.action === 'search_groups') {
            searchGroups();
            return;
        }

        /* ---- Process action if one was sent ---- */
        if (input && input.action) {
            processAction();

            /* Do not reload widget data after a failed action */
            if (data.error) return;
        }

        /* ---- Load full widget data ---- */
        loadData();

    } catch (e) {
        gs.error('FileManagerWidget error: ' + e.message + '\n' + e.stack);
        data.error = 'An unexpected server error occurred. Please refresh and try again.';
    }

    /* ==================================================
       ACTION DISPATCHER
    ================================================== */

    function processAction() {
        switch (input.action) {
            case 'refresh':
                // Explicitly refresh all data
                break;
            case 'create_folder': createFolder(); break;
            case 'rename_folder': renameFolder(); break;
            case 'create_file': createFile(); break;
            case 'update_file': updateFile(); break;
            case 'delete_file': deleteFile(); break;
            case 'delete_folder': deleteFolder(); break;
            case 'restore_file': restoreFile(); break;
            case 'restore_folder': restoreFolder(); break;
            case 'delete_file_permanent': deleteFilePermanent(); break;
            case 'delete_folder_permanent': deleteFolderPermanent(); break;
            case 'share': shareItem(); break;
            case 'empty_bin': emptyBin(); break;
            default:
                data.error = 'Invalid action: ' + (input.action || '');
        }
    }

    /* ==================================================
       HELPERS & SHARED LOGIC
    ================================================== */

    /** Safely fetch a single record by sys_id — returns GlideRecord or null */
    function getRecord(table, sysId) {
        if (!sysId) return null;
        try {
            var gr = new GlideRecord(table);
            if (gr.get(sysId)) return gr;
        } catch (e) { /* ignore */ }
        return null;
    }

    function isDeleted(gr) {
        return gr.getValue('is_deleted') === '1' ||
            gr.getValue('is_deleted') === true;
    }

    /** Check whether a share record is active and not expired */
    function isActiveShare(share) {
        var activeVal = share.getValue('active');
        if (activeVal !== '1' && activeVal !== true && activeVal !== 'true') return false;

        var expiry = share.getValue('expiration_date');
        if (expiry) {
            var expiryDate = new GlideDateTime(expiry);
            var now = new GlideDateTime();
            if (expiryDate.getNumericValue() < now.getNumericValue()) return false;
        }
        return true;
    }

    /** Check if share applies to current user (direct user share OR group membership OR created by user) */
    function isShareForUser(share) {
        if (!isActiveShare(share)) return false;

        var targetUser = share.getValue('shared_with_user');
        if (targetUser && targetUser === userId) return true;

        var targetGroup = share.getValue('shared_with_group');
        if (targetGroup) {
            try {
                if (gs.getUser().isMemberOf(targetGroup)) return true;
            } catch (e) { /* ignore */ }
        }

        var sharedBy = share.getValue('shared_by');
        if (sharedBy && sharedBy === userId) return true;

        return false;
    }

    /** Return the share permission ('Viewer'|'Editor') for current user on an item,
     *  checking both direct user shares and group shares. */
    function getDirectShare(tableField, itemId) {
        var share = new GlideRecord(SHARE_TABLE);
        share.addQuery(tableField, itemId);
        share.addQuery('active', true);

        var qc = share.addQuery('shared_with_user', userId);
        try {
            var myGroups = gs.getUser().getMyGroups();
            if (myGroups && myGroups.size() > 0) {
                qc.addOrCondition('shared_with_group', 'IN', myGroups.toArray().join(','));
            }
        } catch (e) { /* fallback */ }

        qc.addOrCondition('shared_by', userId);

        share.query();

        var bestPerm = '';
        while (share.next()) {
            if (isShareForUser(share)) {
                var perm = share.getValue('permission') || 'Viewer';
                if (perm === 'Editor') return 'Editor'; // Editor overrides Viewer
                bestPerm = perm;
            }
        }
        return bestPerm;
    }

    /** Resolve folder permission for the current user */
    function getFolderPermission(folderId) {
        if (!folderId) return '';
        var folder = getRecord(FOLDER_TABLE, folderId);
        if (!folder || isDeleted(folder)) return '';
        if (folder.getValue('owner') === userId) return 'Owner';
        return getDirectShare('folder', folderId);
    }

    /** Resolve file permission for the current user (file → direct share → folder) */
    function getFilePermission(file) {
        if (!file || isDeleted(file)) return '';
        if (file.getValue('owner') === userId) return 'Owner';

        var direct = getDirectShare('file', file.getUniqueValue());
        if (direct) return direct;

        var folderId = file.getValue('folder');
        if (folderId) return getFolderPermission(folderId);

        return '';
    }

    function canEdit(permission) {
        return permission === 'Owner' || permission === 'Editor';
    }

    function canOwnFile(file) {
        return file && file.getValue('owner') === userId;
    }

    function canOwnFolder(folder) {
        return folder && folder.getValue('owner') === userId;
    }

    /** Return the most recent attachment sys_id for a file record */
    function getAttachmentId(fileId) {
        var att = new GlideRecord('sys_attachment');
        att.addQuery('table_name', FILE_TABLE);
        att.addQuery('table_sys_id', fileId);
        att.orderByDesc('sys_created_on');
        att.setLimit(1);
        att.query();
        if (att.next()) return att.getUniqueValue();
        return '';
    }

    /** Append a file object to a target array — skips if user has no permission */
    function addFileToList(file, target) {
        var permission = getFilePermission(file);
        if (!permission) return;

        var fn = file.getValue('filename') || file.getValue('file_name') || file.getValue('name') || file.getDisplayValue() || '';

        target.push({
            sys_id: file.getUniqueValue(),
            filename: fn,
            folder: file.getValue('folder') || '',
            folder_name: file.getDisplayValue('folder') || '',
            description: file.getValue('description') || '',
            owner: file.getValue('owner') || '',
            file_extension: file.getValue('file_extension') || '',
            file_size: parseInt(file.getValue('file_size'), 10) || 0,
            content_type: file.getValue('content_type') || '',
            attachment_id: getAttachmentId(file.getUniqueValue()),
            permission: permission,
            can_edit: canEdit(permission),
            sys_created_on: file.getValue('sys_created_on') || ''
        });
    }

    /** Append a folder object to a target array — skips if user has no permission */
    function addFolderToList(folder, target) {
        var permission = getFolderPermission(folder.getUniqueValue());
        if (!permission) return;

        var fn = folder.getValue('folder_name') || folder.getValue('name') || folder.getDisplayValue() || '';

        target.push({
            sys_id: folder.getUniqueValue(),
            folder_name: fn,
            parent_folder: folder.getValue('parent_folder') || '',
            description: folder.getValue('description') || '',
            owner: folder.getValue('owner') || '',
            permission: permission,
            can_edit: canEdit(permission)
        });
    }

    /* ==================================================
       SEARCH USERS & GROUPS
    ================================================== */

    function searchUsers() {
        data.users = [];
        var term = (input.search_term || '').trim();
        if (term.length < 2) return;

        var users = new GlideRecord('sys_user');
        users.addQuery('active', true);
        users.addQuery('sys_id', '!=', userId);

        var cond = users.addQuery('name', 'CONTAINS', term);
        cond.addOrCondition('user_name', 'CONTAINS', term);
        cond.addOrCondition('email', 'CONTAINS', term);

        users.orderBy('name');
        users.setLimit(50);
        users.query();

        while (users.next()) {
            data.users.push({
                sys_id: users.getUniqueValue(),
                name: users.getValue('name') || '',
                user_name: users.getValue('user_name') || '',
                email: users.getValue('email') || ''
            });
        }
    }

    function searchGroups() {
        data.groups = [];
        var term = (input.search_term || '').trim();
        if (term.length < 2) return;

        var groups = new GlideRecord('sys_user_group');
        groups.addQuery('active', true);
        groups.addQuery('name', 'CONTAINS', term);
        groups.orderBy('name');
        groups.setLimit(50);
        groups.query();

        while (groups.next()) {
            data.groups.push({
                sys_id: groups.getUniqueValue(),
                name: groups.getValue('name') || '',
                description: groups.getValue('description') || ''
            });
        }
    }

    /* ==================================================
       CREATE FOLDER (with duplicate check)
    ================================================== */

    function createFolder() {
        var folderName = (input.folder_name || '').trim();
        var parentFolder = (input.parent_folder || '').trim();
        var description = (input.description || '').trim();

        if (!folderName) {
            data.error = 'Please enter a folder name.';
            return;
        }
        if (folderName.length > 40) {
            data.error = 'Folder name cannot exceed 40 characters.';
            return;
        }

        /* Permission to create subfolder */
        if (parentFolder) {
            var parent = getRecord(FOLDER_TABLE, parentFolder);
            if (!parent || isDeleted(parent)) {
                data.error = 'Parent folder not found.';
                return;
            }
            if (!canEdit(getFolderPermission(parent.getUniqueValue()))) {
                data.error = 'You do not have permission to create a subfolder here.';
                return;
            }
        }

        /* Duplicate check */
        if (_folderNameExists(folderName, parentFolder, null)) {
            data.error = 'A folder with this name already exists in this location.';
            return;
        }

        var folder = new GlideRecord(FOLDER_TABLE);
        folder.initialize();
        if (folder.isValidField('folder_name')) {
            folder.setValue('folder_name', folderName);
        } else if (folder.isValidField('name')) {
            folder.setValue('name', folderName);
        } else {
            folder.setValue('folder_name', folderName);
        }
        folder.setValue('owner', userId);
        folder.setValue('description', description);
        folder.setValue('is_deleted', false);
        folder.setValue('active', true);
        if (parentFolder) folder.setValue('parent_folder', parentFolder);

        var folderId = folder.insert();
        if (!folderId) {
            data.error = 'Unable to create folder. Please check your permissions.';
            return;
        }

        data.success = 'Folder "' + folderName + '" created successfully.';
        data.folder_sys_id = folderId;
    }

    /* ==================================================
       RENAME FOLDER
    ================================================== */

    function renameFolder() {
        var newName = (input.folder_name || '').trim();
        var targetId = (input.sys_id || '').trim();

        if (!newName || !targetId) {
            data.error = 'Folder ID and new name are required.';
            return;
        }
        if (newName.length > 40) {
            data.error = 'Folder name cannot exceed 40 characters.';
            return;
        }

        var folder = getRecord(FOLDER_TABLE, targetId);
        if (!folder || isDeleted(folder)) {
            data.error = 'Folder not found.';
            return;
        }
        if (!canOwnFolder(folder)) {
            data.error = 'Only the folder owner can rename this folder.';
            return;
        }

        var parentFolder = folder.getValue('parent_folder') || '';

        if (_folderNameExists(newName, parentFolder, targetId)) {
            data.error = 'A folder with this name already exists in this location.';
            return;
        }

        folder.setValue('folder_name', newName);
        if (!folder.update()) {
            data.error = 'Unable to rename folder.';
            return;
        }

        data.success = 'Folder renamed to "' + newName + '".';
    }

    /* ==================================================
       CREATE FILE RECORD
    ================================================== */

    function createFile() {
        var filename = (input.filename || '').trim();
        var folderId = (input.folder || '').trim();

        if (!filename || !folderId) {
            data.error = 'File name and destination folder are required.';
            return;
        }
        if (filename.length > 255) {
            data.error = 'File name is too long (max 255 characters).';
            return;
        }

        var folder = getRecord(FOLDER_TABLE, folderId);
        if (!folder || isDeleted(folder)) {
            data.error = 'Destination folder not found.';
            return;
        }
        if (!canEdit(getFolderPermission(folder.getUniqueValue()))) {
            data.error = 'You do not have permission to upload into this folder.';
            return;
        }

        var file = new GlideRecord(FILE_TABLE);
        file.initialize();
        if (file.isValidField('filename')) {
            file.setValue('filename', filename);
        } else if (file.isValidField('file_name')) {
            file.setValue('file_name', filename);
        } else if (file.isValidField('name')) {
            file.setValue('name', filename);
        } else {
            file.setValue('filename', filename);
        }
        file.setValue('folder', folderId);
        file.setValue('owner', userId);
        file.setValue('file_extension', (input.extension || '').toLowerCase());
        file.setValue('file_size', parseInt(input.file_size, 10) || 0);
        file.setValue('content_type', input.content_type || 'application/octet-stream');
        file.setValue('is_deleted', false);
        file.setValue('current_version', 1);

        var fileId = file.insert();
        if (!fileId) {
            data.error = 'Unable to create file record. Please check your permissions.';
            return;
        }

        data.file_sys_id = fileId;
        data.success = 'File record created.';
    }

    /* ==================================================
       UPDATE FILE DESCRIPTION
    ================================================== */

    function updateFile() {
        var file = getRecord(FILE_TABLE, input.sys_id);
        if (!file || isDeleted(file)) {
            data.error = 'File not found.';
            return;
        }
        if (!canEdit(getFilePermission(file))) {
            data.error = 'You do not have permission to edit this file.';
            return;
        }

        file.setValue('description', (input.description || '').substring(0, 1000));
        if (!file.update()) {
            data.error = 'Unable to update file.';
            return;
        }

        data.success = 'File updated successfully.';
    }

    /* ==================================================
       DELETE FILE (soft)
    ================================================== */

    function deleteFile() {
        var file = getRecord(FILE_TABLE, input.sys_id);
        if (!file || isDeleted(file) || !canOwnFile(file)) {
            data.error = 'Only the file owner can delete this file.';
            return;
        }

        file.setValue('original_folder', file.getValue('folder'));
        file.setValue('is_deleted', true);
        file.setValue('deleted_by', userId);
        file.setValue('deleted_date', new GlideDateTime());
        file.update();

        data.success = 'File moved to Recycle Bin.';
    }

    /* ==================================================
       DELETE FOLDER (soft — must be empty)
    ================================================== */

    function deleteFolder() {
        var folder = getRecord(FOLDER_TABLE, input.sys_id);
        if (!folder || isDeleted(folder) || !canOwnFolder(folder)) {
            data.error = 'Only the folder owner can delete this folder.';
            return;
        }

        /* Ensure no active sub-folders */
        var childFolders = new GlideRecord(FOLDER_TABLE);
        childFolders.addQuery('parent_folder', folder.getUniqueValue());
        childFolders.addQuery('is_deleted', false);
        childFolders.setLimit(1);
        childFolders.query();
        if (childFolders.hasNext()) {
            data.error = 'Please delete or move all subfolders first.';
            return;
        }

        /* Ensure no active files */
        var files = new GlideRecord(FILE_TABLE);
        files.addQuery('folder', folder.getUniqueValue());
        files.addQuery('is_deleted', false);
        files.setLimit(1);
        files.query();
        if (files.hasNext()) {
            data.error = 'Please delete or move all files in this folder first.';
            return;
        }

        folder.setValue('is_deleted', true);
        folder.setValue('deleted_by', userId);
        folder.setValue('deleted_date', new GlideDateTime());
        folder.setValue('active', false);
        folder.update();

        data.success = 'Folder moved to Recycle Bin.';
    }

    /* ==================================================
       RESTORE FILE
    ================================================== */

    function restoreFile() {
        var file = getRecord(FILE_TABLE, input.sys_id);
        if (!file || !canOwnFile(file) || !isDeleted(file)) {
            data.error = 'You cannot restore this file.';
            return;
        }

        var originalFolder = file.getValue('original_folder');
        if (originalFolder) {
            var folder = getRecord(FOLDER_TABLE, originalFolder);
            if (!folder || isDeleted(folder)) {
                data.error = 'The original folder no longer exists. Please restore it first.';
                return;
            }
            file.setValue('folder', originalFolder);
        }

        file.setValue('is_deleted', false);
        file.setValue('deleted_by', '');
        file.setValue('deleted_date', '');
        file.setValue('original_folder', '');
        file.update();

        data.success = 'File restored successfully.';
    }

    /* ==================================================
       RESTORE FOLDER
    ================================================== */

    function restoreFolder() {
        var folder = getRecord(FOLDER_TABLE, input.sys_id);
        if (!folder || !canOwnFolder(folder) || !isDeleted(folder)) {
            data.error = 'You cannot restore this folder.';
            return;
        }

        var parentId = folder.getValue('parent_folder');
        if (parentId) {
            var parent = getRecord(FOLDER_TABLE, parentId);
            if (!parent || isDeleted(parent)) {
                data.error = 'Please restore the parent folder first.';
                return;
            }
        }

        if (_folderNameExists(
            folder.getValue('folder_name'),
            parentId || '',
            folder.getUniqueValue()
        )) {
            data.error = 'A folder with this name already exists in that location.';
            return;
        }

        folder.setValue('is_deleted', false);
        folder.setValue('deleted_by', '');
        folder.setValue('deleted_date', '');
        folder.setValue('active', true);
        folder.update();

        data.success = 'Folder restored successfully.';
    }

    /* ==================================================
       EMPTY RECYCLE BIN (permanent delete)
    ================================================== */

    function emptyBin() {
        /* Delete files */
        var files = new GlideRecord(FILE_TABLE);
        files.addQuery('owner', userId);
        files.addQuery('is_deleted', true);
        files.query();
        while (files.next()) {
            /* Also delete attached attachment records */
            var att = new GlideRecord('sys_attachment');
            att.addQuery('table_name', FILE_TABLE);
            att.addQuery('table_sys_id', files.getUniqueValue());
            att.query();
            att.deleteMultiple();

            files.deleteRecord();
        }

        /* Delete folders */
        var folders = new GlideRecord(FOLDER_TABLE);
        folders.addQuery('owner', userId);
        folders.addQuery('is_deleted', true);
        folders.query();
        folders.deleteMultiple();

        data.success = 'Recycle Bin emptied.';
    }

    /* ==================================================
       PERMANENT DELETE INDIVIDUAL ITEM
    ================================================== */

    function deleteFilePermanent() {
        var file = getRecord(FILE_TABLE, input.sys_id);
        if (!file || !canOwnFile(file) || !isDeleted(file)) {
            data.error = 'You cannot permanently delete this file.';
            return;
        }

        var att = new GlideRecord('sys_attachment');
        att.addQuery('table_name', FILE_TABLE);
        att.addQuery('table_sys_id', file.getUniqueValue());
        att.query();
        att.deleteMultiple();

        file.deleteRecord();
        data.success = 'File permanently deleted.';
    }

    function deleteFolderPermanent() {
        var folder = getRecord(FOLDER_TABLE, input.sys_id);
        if (!folder || !canOwnFolder(folder) || !isDeleted(folder)) {
            data.error = 'You cannot permanently delete this folder.';
            return;
        }

        folder.deleteRecord();
        data.success = 'Folder permanently deleted.';
    }

    /* ==================================================
       SHARE FILE OR FOLDER
    ================================================== */

    function shareItem() {
        var type = (input.type || '');
        var itemId = (input.sys_id || '');
        var shareRecipient = (input.recipient_type || 'user'); // 'user' | 'group'
        var targetUser = (input.user_id || '');
        var targetGroup = (input.group_id || '');
        var permission = (input.permission || '');
        var expirationDate = (input.expiration_date || '');

        if (!itemId) {
            data.error = 'No item specified to share.';
            return;
        }

        if (permission !== 'Viewer' && permission !== 'Editor') {
            data.error = 'Invalid permission level.';
            return;
        }

        var targetField;
        if (type === 'file') {
            var item = getRecord(FILE_TABLE, itemId);
            if (!item || isDeleted(item) || !canOwnFile(item)) {
                data.error = 'Only the file owner can share this file.';
                return;
            }
            targetField = 'file';
        } else if (type === 'folder') {
            var item2 = getRecord(FOLDER_TABLE, itemId);
            if (!item2 || isDeleted(item2) || !canOwnFolder(item2)) {
                data.error = 'Only the folder owner can share this folder.';
                return;
            }
            targetField = 'folder';
        } else {
            data.error = 'Invalid item type.';
            return;
        }

        var existing = new GlideRecord(SHARE_TABLE);
        existing.addQuery(targetField, itemId);

        if (shareRecipient === 'group') {
            if (!targetGroup) {
                data.error = 'Please select a group.';
                return;
            }
            var grp = new GlideRecord('sys_user_group');
            if (!grp.get(targetGroup) || grp.getValue('active') !== '1') {
                data.error = 'Selected group is not available.';
                return;
            }
            existing.addQuery('shared_with_group', targetGroup);
        } else {
            if (!targetUser) {
                data.error = 'Please select a user.';
                return;
            }
            if (targetUser === userId) {
                data.error = 'You cannot share an item with yourself.';
                return;
            }
            var user = new GlideRecord('sys_user');
            if (!user.get(targetUser) || user.getValue('active') !== '1') {
                data.error = 'The selected user is not available.';
                return;
            }
            existing.addQuery('shared_with_user', targetUser);
        }

        existing.query();

        // Sanitize expiration date if provided
        var formattedExpiry = '';
        if (expirationDate) {
            try {
                formattedExpiry = String(expirationDate).replace('T', ' ').replace(/\.\d+Z?$/, '');
                if (formattedExpiry.length === 16) formattedExpiry += ':00';
            } catch (e) {
                formattedExpiry = '';
            }
        }

        if (existing.next()) {
            existing.setValue('active', true);
            existing.setValue('permission', permission);
            existing.setValue('shared_by', userId);
            if (shareRecipient === 'group') {
                existing.setValue('shared_with_group', targetGroup);
                existing.setValue('shared_with_user', '');
            } else {
                existing.setValue('shared_with_user', targetUser);
                existing.setValue('shared_with_group', '');
            }
            if (formattedExpiry) {
                existing.setValue('expiration_date', formattedExpiry);
            } else {
                existing.setValue('expiration_date', '');
            }
            existing.update();
        } else {
            var share = new GlideRecord(SHARE_TABLE);
            share.initialize();
            share.setValue(targetField, itemId);
            if (targetField === 'file') share.setValue('folder', '');
            if (targetField === 'folder') share.setValue('file', '');

            if (shareRecipient === 'group') {
                share.setValue('shared_with_group', targetGroup);
                share.setValue('shared_with_user', '');
            } else {
                share.setValue('shared_with_user', targetUser);
                share.setValue('shared_with_group', '');
            }
            share.setValue('shared_by', userId);
            share.setValue('permission', permission);
            share.setValue('active', true);
            if (formattedExpiry) {
                share.setValue('expiration_date', formattedExpiry);
            }
            if (!share.insert()) {
                data.error = 'Unable to share this item. Please try again.';
                return;
            }
        }

        data.success = 'Item shared successfully as ' + permission + '.';
    }

    /* ==================================================
       LOAD WIDGET DATA
    ================================================== */

    function loadData() {
        loadOwnedFolders();
        loadOwnedFiles();
        loadSharedItems();
        loadRecycleBin();
        loadStorage();
    }

    function loadOwnedFolders() {
        var folders = new GlideRecord(FOLDER_TABLE);
        folders.addQuery('owner', userId);
        folders.addQuery('is_deleted', false);
        folders.orderBy('folder_name');
        folders.query();
        while (folders.next()) addFolderToList(folders, data.folders);
    }

    function loadOwnedFiles() {
        var files = new GlideRecord(FILE_TABLE);
        files.addQuery('owner', userId);
        files.addQuery('is_deleted', false);
        files.orderByDesc('sys_created_on');
        files.query();
        while (files.next()) addFileToList(files, data.files);
    }

    function loadSharedItems() {
        var shares = new GlideRecord(SHARE_TABLE);
        shares.addQuery('active', true);

        // Find shares:
        // 1) Shared with current user
        // 2) Shared with a group current user belongs to
        // 3) Shared BY current user (so items shared by you are populated and counted!)
        var qc = shares.addQuery('shared_with_user', userId);
        try {
            var myGroups = gs.getUser().getMyGroups();
            if (myGroups && myGroups.size() > 0) {
                qc.addOrCondition('shared_with_group', 'IN', myGroups.toArray().join(','));
            }
        } catch (e) { /* fallback */ }

        qc.addOrCondition('shared_by', userId);

        shares.query();

        var seenFiles = {};
        var seenFolders = {};

        while (shares.next()) {
            if (!isActiveShare(shares)) continue;

            var fileId = shares.getValue('file');
            var folderId = shares.getValue('folder');

            if (fileId && !seenFiles[fileId]) {
                seenFiles[fileId] = true;
                var file = getRecord(FILE_TABLE, fileId);
                if (file && !isDeleted(file)) {
                    addFileToList(file, data.sharedFiles);
                }
            }

            if (folderId && !seenFolders[folderId]) {
                seenFolders[folderId] = true;
                var shFolder = getRecord(FOLDER_TABLE, folderId);
                if (shFolder && !isDeleted(shFolder)) {
                    addFolderToList(shFolder, data.sharedFolders);

                    // Also load all files inside this shared folder
                    var folderFiles = new GlideRecord(FILE_TABLE);
                    folderFiles.addQuery('folder', folderId);
                    folderFiles.addQuery('is_deleted', false);
                    folderFiles.query();
                    while (folderFiles.next()) {
                        var fSysId = folderFiles.getUniqueValue();
                        if (!seenFiles[fSysId]) {
                            seenFiles[fSysId] = true;
                            addFileToList(folderFiles, data.sharedFiles);
                        }
                    }
                }
            }
        }
    }

    function loadRecycleBin() {
        var files = new GlideRecord(FILE_TABLE);
        files.addQuery('owner', userId);
        files.addQuery('is_deleted', true);
        files.orderByDesc('deleted_date');
        files.query();

        while (files.next()) {
            var deletedDate = files.getValue('deleted_date') || '';
            if (deletedDate) {
                try {
                    var gdt = new GlideDateTime(deletedDate);
                    deletedDate = gdt.getLocalDate().getLocalDate();
                } catch (e) { /* keep raw value */ }
            }

            data.recycleFiles.push({
                sys_id: files.getUniqueValue(),
                filename: files.getValue('filename') || '',
                file_size: parseInt(files.getValue('file_size'), 10) || 0,
                file_extension: files.getValue('file_extension') || '',
                deleted_date: deletedDate
            });
        }

        var folders = new GlideRecord(FOLDER_TABLE);
        folders.addQuery('owner', userId);
        folders.addQuery('is_deleted', true);
        folders.orderByDesc('deleted_date');
        folders.query();

        while (folders.next()) {
            var dDate = folders.getValue('deleted_date') || '';
            if (dDate) {
                try {
                    var gdt2 = new GlideDateTime(dDate);
                    dDate = gdt2.getLocalDate().getLocalDate();
                } catch (e) { /* keep raw value */ }
            }

            data.recycleFolders.push({
                sys_id: folders.getUniqueValue(),
                folder_name: folders.getValue('folder_name') || '',
                deleted_date: dDate
            });
        }
    }

    function loadStorage() {
        var byType = {};

        var files = new GlideRecord(FILE_TABLE);
        files.addQuery('owner', userId);
        files.addQuery('is_deleted', false);
        files.query();

        while (files.next()) {
            var size = parseInt(files.getValue('file_size'), 10) || 0;
            var ext = (files.getValue('file_extension') || 'unknown').toLowerCase();

            data.storage.fileCount++;
            data.storage.totalBytes += size;

            if (!byType[ext]) byType[ext] = { ext: ext, count: 0, totalBytes: 0 };
            byType[ext].count++;
            byType[ext].totalBytes += size;
        }

        /* Convert map to sorted array */
        for (var key in byType) {
            if (byType.hasOwnProperty(key)) data.storage.byType.push(byType[key]);
        }
        data.storage.byType.sort(function (a, b) { return b.totalBytes - a.totalBytes; });
    }

    /* ==================================================
       PRIVATE HELPERS
    ================================================== */

    /**
     * Check whether a folder with 'name' already exists (non-deleted) at a
     * given parent location, owned by the current user.
     *
     * @param {string} name         Folder name to check
     * @param {string} parentFolder Parent folder sys_id (or '' for root)
     * @param {string} excludeId    sys_id to exclude (the folder being renamed)
     */
    function _folderNameExists(name, parentFolder, excludeId) {
        var dup = new GlideRecord(FOLDER_TABLE);
        dup.addQuery('owner', userId);
        dup.addQuery('folder_name', name);
        dup.addQuery('is_deleted', false);

        if (excludeId) dup.addQuery('sys_id', '!=', excludeId);

        if (parentFolder) {
            dup.addQuery('parent_folder', parentFolder);
        } else {
            dup.addNullQuery('parent_folder');
        }

        dup.setLimit(1);
        dup.query();
        return dup.hasNext();
    }

})();
